// Build with the distribution's Vulkan headers and loader. transform_spv is generated by glslang.
#define _POSIX_C_SOURCE 200809L
#include <inttypes.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <vulkan/vulkan.h>
#include "transform.h"

#define VK_CHECK(call)                                                                                       \
    do {                                                                                                     \
        VkResult r = (call);                                                                                 \
        if (r != VK_SUCCESS) {                                                                               \
            fprintf(stderr, "%s: VkResult %d\n", #call, r);                                                  \
            exit(1);                                                                                         \
        }                                                                                                    \
    } while (0)

enum { WORDS = 64 * 1024 };

static uint64_t now_ns(void) {
    struct timespec ts;
    if (clock_gettime(CLOCK_MONOTONIC, &ts) < 0) {
        perror("clock_gettime");
        exit(1);
    }
    return (uint64_t)ts.tv_sec * 1000000000 + ts.tv_nsec;
}

static uint32_t input(uint32_t i) { return i ^ 0xcafe1234u; }

static VkPhysicalDevice choose_device(VkInstance instance, bool software_control) {
    uint32_t count = 0;
    VK_CHECK(vkEnumeratePhysicalDevices(instance, &count, NULL));
    VkPhysicalDevice *devices = calloc(count, sizeof(*devices));
    if (!count || !devices) {
        fprintf(stderr, "No physical device list\n");
        exit(1);
    }
    VK_CHECK(vkEnumeratePhysicalDevices(instance, &count, devices));
    VkPhysicalDevice selected = VK_NULL_HANDLE;
    for (uint32_t i = 0; i < count; i++) {
        VkPhysicalDeviceDriverProperties driver = {.sType =
                                                       VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_DRIVER_PROPERTIES};
        VkPhysicalDeviceProperties2 props = {.sType = VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2,
                                             .pNext = &driver};
        vkGetPhysicalDeviceProperties2(devices[i], &props);
        printf("device=%s type=%d driver=%s driverID=%d\n", props.properties.deviceName,
               props.properties.deviceType, driver.driverName, driver.driverID);
        bool cpu = props.properties.deviceType == VK_PHYSICAL_DEVICE_TYPE_CPU;
        if (!selected && (software_control ? cpu : (!cpu && driver.driverID == VK_DRIVER_ID_MESA_VENUS)))
            selected = devices[i];
    }
    free(devices);
    if (!selected) {
        fprintf(stderr, "No %s device\n", software_control ? "CPU control" : "hardware Venus");
        exit(1);
    }
    return selected;
}

int main(int argc, char **argv) {
    bool control = argc == 2 && strcmp(argv[1], "--software-control") == 0;
    bool victim = argc == 2 && strcmp(argv[1], "--kill-in-flight") == 0;
    if (argc != 1 && !control && !victim) {
        fprintf(stderr, "Usage: %s [--software-control | --kill-in-flight]\n", argv[0]);
        return 2;
    }
    const uint64_t start = now_ns();
    VkApplicationInfo app = {.sType = VK_STRUCTURE_TYPE_APPLICATION_INFO, .apiVersion = VK_API_VERSION_1_2};
    VkInstanceCreateInfo ci = {.sType = VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO, .pApplicationInfo = &app};
    VkInstance instance;
    VK_CHECK(vkCreateInstance(&ci, NULL, &instance));
    VkPhysicalDevice gpu = choose_device(instance, control);
    uint32_t count = 0;
    vkGetPhysicalDeviceQueueFamilyProperties(gpu, &count, NULL);
    VkQueueFamilyProperties *families = calloc(count, sizeof(*families));
    if (!families)
        return 1;
    vkGetPhysicalDeviceQueueFamilyProperties(gpu, &count, families);
    uint32_t family = 0;
    while (family < count && !(families[family].queueFlags & VK_QUEUE_COMPUTE_BIT))
        family++;
    free(families);
    if (family == count) {
        fprintf(stderr, "No compute queue\n");
        return 1;
    }
    float priority = 1;
    VkDeviceQueueCreateInfo qci = {.sType = VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO,
                                   .queueFamilyIndex = family,
                                   .queueCount = 1,
                                   .pQueuePriorities = &priority};
    VkDeviceCreateInfo dci = {
        .sType = VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO, .queueCreateInfoCount = 1, .pQueueCreateInfos = &qci};
    VkDevice device;
    VK_CHECK(vkCreateDevice(gpu, &dci, NULL, &device));
    VkQueue queue;
    vkGetDeviceQueue(device, family, 0, &queue);

    VkBufferCreateInfo bci = {.sType = VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO,
                              .size = WORDS * 4,
                              .usage = VK_BUFFER_USAGE_STORAGE_BUFFER_BIT,
                              .sharingMode = VK_SHARING_MODE_EXCLUSIVE};
    VkBuffer buffer;
    VK_CHECK(vkCreateBuffer(device, &bci, NULL, &buffer));
    VkMemoryRequirements req;
    vkGetBufferMemoryRequirements(device, buffer, &req);
    VkPhysicalDeviceMemoryProperties mp;
    vkGetPhysicalDeviceMemoryProperties(gpu, &mp);
    uint32_t type = 0;
    while (type < mp.memoryTypeCount &&
           (!(req.memoryTypeBits & (1u << type)) ||
            !(mp.memoryTypes[type].propertyFlags & VK_MEMORY_PROPERTY_HOST_VISIBLE_BIT)))
        type++;
    if (type == mp.memoryTypeCount) {
        fprintf(stderr, "No host-visible buffer memory\n");
        return 1;
    }
    VkMemoryAllocateInfo alloc = {
        .sType = VK_STRUCTURE_TYPE_MEMORY_ALLOCATE_INFO, .allocationSize = req.size, .memoryTypeIndex = type};
    VkDeviceMemory memory;
    VK_CHECK(vkAllocateMemory(device, &alloc, NULL, &memory));
    VK_CHECK(vkBindBufferMemory(device, buffer, memory, 0));
    void *mapped;
    VK_CHECK(vkMapMemory(device, memory, 0, VK_WHOLE_SIZE, 0, &mapped));
    uint32_t *data = mapped;
    VkMappedMemoryRange range = {
        .sType = VK_STRUCTURE_TYPE_MAPPED_MEMORY_RANGE, .memory = memory, .size = VK_WHOLE_SIZE};
    uint64_t upload = now_ns();
    for (uint32_t i = 0; i < WORDS; i++)
        data[i] = input(i);
    VK_CHECK(vkFlushMappedMemoryRanges(device, 1, &range));
    upload = now_ns() - upload;

    VkDescriptorSetLayoutBinding binding = {.binding = 0,
                                            .descriptorType = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER,
                                            .descriptorCount = 1,
                                            .stageFlags = VK_SHADER_STAGE_COMPUTE_BIT};
    VkDescriptorSetLayoutCreateInfo slci = {.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO,
                                            .bindingCount = 1,
                                            .pBindings = &binding};
    VkDescriptorSetLayout sl;
    VK_CHECK(vkCreateDescriptorSetLayout(device, &slci, NULL, &sl));
    VkPipelineLayoutCreateInfo plci = {
        .sType = VK_STRUCTURE_TYPE_PIPELINE_LAYOUT_CREATE_INFO, .setLayoutCount = 1, .pSetLayouts = &sl};
    VkPipelineLayout pl;
    VK_CHECK(vkCreatePipelineLayout(device, &plci, NULL, &pl));
    VkShaderModuleCreateInfo smci = {.sType = VK_STRUCTURE_TYPE_SHADER_MODULE_CREATE_INFO,
                                     .codeSize = sizeof(transform_spv),
                                     .pCode = transform_spv};
    VkShaderModule shader;
    VK_CHECK(vkCreateShaderModule(device, &smci, NULL, &shader));
    VkComputePipelineCreateInfo cpci = {
        .sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO,
        .stage = {.sType = VK_STRUCTURE_TYPE_PIPELINE_SHADER_STAGE_CREATE_INFO,
                  .stage = VK_SHADER_STAGE_COMPUTE_BIT,
                  .module = shader,
                  .pName = "main"},
        .layout = pl};
    VkPipeline pipeline;
    VK_CHECK(vkCreateComputePipelines(device, VK_NULL_HANDLE, 1, &cpci, NULL, &pipeline));
    VkDescriptorPoolSize ps = {.type = VK_DESCRIPTOR_TYPE_STORAGE_BUFFER, .descriptorCount = 1};
    VkDescriptorPoolCreateInfo dpci = {.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO,
                                       .maxSets = 1,
                                       .poolSizeCount = 1,
                                       .pPoolSizes = &ps};
    VkDescriptorPool descriptors;
    VK_CHECK(vkCreateDescriptorPool(device, &dpci, NULL, &descriptors));
    VkDescriptorSetAllocateInfo dsai = {.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO,
                                        .descriptorPool = descriptors,
                                        .descriptorSetCount = 1,
                                        .pSetLayouts = &sl};
    VkDescriptorSet set;
    VK_CHECK(vkAllocateDescriptorSets(device, &dsai, &set));
    VkDescriptorBufferInfo bi = {.buffer = buffer, .range = bci.size};
    VkWriteDescriptorSet update = {.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET,
                                   .dstSet = set,
                                   .dstBinding = 0,
                                   .descriptorCount = 1,
                                   .descriptorType = ps.type,
                                   .pBufferInfo = &bi};
    vkUpdateDescriptorSets(device, 1, &update, 0, NULL);
    VkCommandPoolCreateInfo pci = {.sType = VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO,
                                   .queueFamilyIndex = family};
    VkCommandPool pool;
    VK_CHECK(vkCreateCommandPool(device, &pci, NULL, &pool));
    VkCommandBufferAllocateInfo cai = {.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO,
                                       .commandPool = pool,
                                       .level = VK_COMMAND_BUFFER_LEVEL_PRIMARY,
                                       .commandBufferCount = 1};
    VkCommandBuffer cmd;
    VK_CHECK(vkAllocateCommandBuffers(device, &cai, &cmd));
    VkCommandBufferBeginInfo begin = {.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
    VK_CHECK(vkBeginCommandBuffer(cmd, &begin));
    vkCmdBindPipeline(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, pipeline);
    vkCmdBindDescriptorSets(cmd, VK_PIPELINE_BIND_POINT_COMPUTE, pl, 0, 1, &set, 0, NULL);
    VkMemoryBarrier between = {.sType = VK_STRUCTURE_TYPE_MEMORY_BARRIER,
                               .srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT,
                               .dstAccessMask = VK_ACCESS_SHADER_READ_BIT | VK_ACCESS_SHADER_WRITE_BIT};
    unsigned dispatches = victim ? 64 : 1;
    for (unsigned i = 0; i < dispatches; i++) {
        if (i)
            vkCmdPipelineBarrier(cmd, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
                                 VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &between, 0, NULL, 0, NULL);
        vkCmdDispatch(cmd, WORDS / 64, 1, 1);
    }
    VkMemoryBarrier barrier = {.sType = VK_STRUCTURE_TYPE_MEMORY_BARRIER,
                               .srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT,
                               .dstAccessMask = VK_ACCESS_HOST_READ_BIT};
    vkCmdPipelineBarrier(cmd, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, VK_PIPELINE_STAGE_HOST_BIT, 0, 1,
                         &barrier, 0, NULL, 0, NULL);
    VK_CHECK(vkEndCommandBuffer(cmd));
    VkSubmitInfo submit = {
        .sType = VK_STRUCTURE_TYPE_SUBMIT_INFO, .commandBufferCount = 1, .pCommandBuffers = &cmd};
    VkFenceCreateInfo fci = {.sType = VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};
    VkFence fence;
    VK_CHECK(vkCreateFence(device, &fci, NULL, &fence));
    uint64_t before_submit = now_ns();
    VK_CHECK(vkQueueSubmit(queue, 1, &submit, fence));
    uint64_t after_submit = now_ns();
    if (victim) {
        if (vkGetFenceStatus(device, fence) != VK_NOT_READY) {
            fprintf(stderr, "Submission completed before termination test\n");
            return 1;
        }
        puts("Terminating with an unsignaled submission fence");
        fflush(stdout);
        kill(getpid(), SIGKILL);
        return 1;
    }
    VK_CHECK(vkWaitForFences(device, 1, &fence, VK_TRUE, 30000000000ull));
    uint64_t readback = now_ns();
    VK_CHECK(vkInvalidateMappedMemoryRanges(device, 1, &range));
    for (uint32_t i = 0; i < WORDS; i++) {
        uint32_t expected = input(i) * 3u + i;
        if (data[i] != expected) {
            fprintf(stderr, "Mismatch at %u: %#x, expected %#x\n", i, data[i], expected);
            return 1;
        }
    }
    uint64_t end = now_ns();
    printf("verified=%u upload_ns=%" PRIu64 " submit_ns=%" PRIu64 " fence_ns=%" PRIu64
           " read_verify_ns=%" PRIu64 " end_to_end_ns=%" PRIu64 "\n",
           WORDS, upload, after_submit - before_submit, readback - after_submit, end - readback, end - start);
    vkDestroyFence(device, fence, NULL);
    vkDestroyCommandPool(device, pool, NULL);
    vkDestroyDescriptorPool(device, descriptors, NULL);
    vkDestroyPipeline(device, pipeline, NULL);
    vkDestroyShaderModule(device, shader, NULL);
    vkDestroyPipelineLayout(device, pl, NULL);
    vkDestroyDescriptorSetLayout(device, sl, NULL);
    vkUnmapMemory(device, memory);
    vkDestroyBuffer(device, buffer, NULL);
    vkFreeMemory(device, memory, NULL);
    vkDestroyDevice(device, NULL);
    vkDestroyInstance(instance, NULL);
    return 0;
}
